schemas:
{
    "@context": "https://schema.org",
    "@type": "FAQPage",
    "mainEntity": [
      {
        "@type": "Question",
        "name": "Perusahaan apa saja yang wajib menerapkan SMK3?",
        "acceptedAnswer": {"@type": "Answer", "text": "Berdasarkan PP No. 50 Tahun 2012, perusahaan dengan 100 karyawan atau lebih, ATAU perusahaan dengan tingkat risiko tinggi (seperti pertambangan, konstruksi, kimia, migas) wajib menerapkan SMK3, terlepas dari jumlah karyawan."}
      },
      {
        "@type": "Question",
        "name": "Berapa banyak elemen dalam SMK3 PP 50/2012?",
        "acceptedAnswer": {"@type": "Answer", "text": "SMK3 berdasarkan PP No. 50 Tahun 2012 memiliki 5 prinsip utama dan 12 elemen yang menjadi dasar audit SMK3. Tingkat pemenuhan dibagi menjadi 3 tingkatan: awal (64 kriteria), transisi (122 kriteria), dan lanjutan (166 kriteria)."}
      },
      {
        "@type": "Question",
        "name": "Apa sanksi perusahaan yang tidak menerapkan SMK3?",
        "acceptedAnswer": {"@type": "Answer", "text": "Perusahaan yang wajib namun tidak menerapkan SMK3 dapat dikenai sanksi administratif berupa teguran tertulis, pembatasan operasional, atau penghentian sementara kegiatan produksi oleh Pengawas Ketenagakerjaan."}
      }
    ]
  }

inline_styles:
@import url('https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap');

    :root {
      --green-dark: #0A4A2E;
      --green-mid: #1a6b45;
      --green-light: #e8f5ee;
      --accent: #f0a500;
      --text: #1a1a2e;
      --muted: #6b7280;
      --border: #e5e7eb;
      --red-light: #fef2f2;
      --red: #dc2626;
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body { max-width: 100%; overflow-x: hidden; }
    body { font-family: 'Plus Jakarta Sans', sans-serif; color: var(--text); background: #fafaf8; line-height: 1.7; }

    nav { background: var(--green-dark); padding: 16px 24px; display: flex; align-items: center; justify-content: space-between; }
    nav a.logo { color: white; text-decoration: none; font-weight: 800; font-size: 1.1rem; }
    nav a.cta-nav { background: var(--accent); color: #1a1a00; padding: 8px 18px; border-radius: 6px; text-decoration: none; font-weight: 700; font-size: 0.85rem; }

    .hero { background: linear-gradient(135deg, var(--green-dark) 0%, #1a6b45 100%); color: white; padding: 60px 24px 48px; text-align: center; }
    .hero .tag { display: inline-block; background: rgba(255,255,255,0.15); border: 1px solid rgba(255,255,255,0.3); padding: 4px 14px; border-radius: 20px; font-size: 0.8rem; font-weight: 600; letter-spacing: 0.05em; margin-bottom: 18px; text-transform: uppercase; }
    .hero h1 { font-size: clamp(1.6rem, 4vw, 2.4rem); font-weight: 800; line-height: 1.25; max-width: 700px; margin: 0 auto 16px; }
    .hero p { font-size: 1.05rem; opacity: 0.88; max-width: 560px; margin: 0 auto 0; }

    .container { max-width: 820px; margin: 0 auto; padding: 0 24px; }
    .article-body { padding: 48px 0 80px; }

    h2 { font-size: 1.4rem; font-weight: 800; color: var(--green-dark); margin: 40px 0 14px; padding-bottom: 8px; border-bottom: 2px solid var(--green-light); }
    h3 { font-size: 1.05rem; font-weight: 700; color: var(--text); margin: 22px 0 8px; }
    p { margin-bottom: 16px; color: #374151; }

    .breadcrumb { padding: 14px 0; font-size: 0.82rem; color: var(--muted); }
    .breadcrumb a { color: var(--green-mid); text-decoration: none; }

    .info-box { background: var(--green-light); border-left: 4px solid var(--green-dark); border-radius: 8px; padding: 18px 20px; margin: 24px 0; }
    .info-box strong { color: var(--green-dark); }

    .warning-box { background: var(--red-light); border-left: 4px solid var(--red); border-radius: 8px; padding: 18px 20px; margin: 24px 0; }
    .warning-box strong { color: var(--red); }

    /* 5 PRINSIP */
    .prinsip-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 12px; margin: 20px 0; }
    .prinsip-card { background: white; border: 1px solid var(--border); border-radius: 10px; padding: 16px; }
    .prinsip-card .num { font-size: 1.8rem; font-weight: 800; color: var(--green-light); margin-bottom: 4px; }
    .prinsip-card h4 { font-size: 0.88rem; font-weight: 700; color: var(--green-dark); margin-bottom: 4px; }
    .prinsip-card p { font-size: 0.8rem; margin: 0; color: var(--muted); }

    /* ELEMEN TABLE */
    table { width: 100%; border-collapse: collapse; margin: 16px 0; font-size: 0.9rem; }
    th { background: var(--green-dark); color: white; padding: 10px 14px; text-align: left; font-weight: 600; }
    td { padding: 10px 14px; border-bottom: 1px solid var(--border); }
    tr:nth-child(even) td { background: #f9fafb; }

    /* TINGKATAN BOX */
    .tingkat-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: 14px; margin: 20px 0; }
    .tingkat-card { border-radius: 12px; padding: 18px; text-align: center; }
    .tingkat-card.awal { background: #fffbeb; border: 2px solid #f59e0b; }
    .tingkat-card.transisi { background: #eff6ff; border: 2px solid #3b82f6; }
    .tingkat-card.lanjutan { background: var(--green-light); border: 2px solid var(--green-mid); }
    .tingkat-card .label { font-weight: 800; font-size: 1rem; margin-bottom: 4px; }
    .tingkat-card .sub { font-size: 0.82rem; color: var(--muted); margin-bottom: 8px; }
    .tingkat-card .criteria { font-size: 1.4rem; font-weight: 800; }

    /* CTA */
    .cta-block { background: linear-gradient(135deg, var(--green-dark), var(--green-mid)); color: white; border-radius: 16px; padding: 36px 28px; text-align: center; margin: 40px 0; }
    .cta-block h3 { color: white; font-size: 1.3rem; margin-bottom: 10px; }
    .cta-block p { color: rgba(255,255,255,0.85); margin-bottom: 22px; }
    .btn-wa { display: inline-flex; align-items: center; gap: 8px; background: #25D366; color: white; padding: 14px 28px; border-radius: 8px; text-decoration: none; font-weight: 700; font-size: 1rem; transition: transform 0.2s; }
    .btn-wa:hover { transform: translateY(-2px); }

    /* FAQ */
    .faq-item { border: 1px solid var(--border); border-radius: 10px; margin-bottom: 12px; overflow: hidden; }
    .faq-q { background: white; padding: 16px 20px; font-weight: 700; font-size: 0.95rem; display: flex; justify-content: space-between; }
    .faq-q::after { content: "▾"; color: var(--green-mid); }
    .faq-a { padding: 14px 20px; background: #f9fafb; font-size: 0.93rem; color: #4b5563; border-top: 1px solid var(--border); }

    footer { background: var(--green-dark); color: rgba(255,255,255,0.75); text-align: center; padding: 28px 24px; font-size: 0.85rem; }
    footer a { color: var(--accent); text-decoration: none; }
